## Why This Question Is Asked
This question tests dynamic programming intuition on a constrained path counting problem with simple transitions and boundary conditions.

## Key Concepts
- **Recurrence relation:** f(i) = f(i+1) + f(i+2) with modulo arithmetic
- **Memoization vs. tabulation:** Trade-offs between recursive top-down with caching versus iterative bottom-up approaches
- **Edge conditions:** Blocked start/end positions, single-cell arrays

## Code Example
```javascript
function countPaths(blocked) {
  const n = blocked.length;
  const MOD = 1000000007;
  if (blocked[0]) return 0;

  // Memoized DFS
  const memo = Array(n).fill(-1);
  function dfs(i) {
    if (i === n - 1) return blocked[i] ? 0 : 1;
    if (i >= n || blocked[i]) return 0;
    if (memo[i] !== -1) return memo[i];
    memo[i] = (dfs(i + 1) + dfs(i + 2)) % MOD;
    return memo[i];
  }
  return dfs(0);
}

// Bottom-up DP (O(1) space)
function countPathsDP(blocked) {
  const n = blocked.length;
  const MOD = 1000000007;
  if (blocked[0]) return 0;

  let next2 = 1, next1 = blocked[n - 1] ? 0 : 1;
  for (let i = n - 2; i >= 0; i--) {
    const curr = blocked[i] ? 0 : (next1 + next2) % MOD;
    next2 = next1;
    next1 = curr;
  }
  return next1;
}
```

## Why This Is Asked
Tests ability to adapt sorting techniques to handle duplicate elements efficiently and to analyze complexity trade-offs between quicksort variants and mergesort.

## Key Concepts
- Three-way partition using Dutch national flag algorithm
- Average vs worst-case complexity with duplicate keys
- In-place sorting with tail recursion optimization
- Space complexity comparison between quicksort and mergesort

## Code Example
```javascript
// Skeleton: threeWayQuicksort(a, lo, hi) with lt/gt pointers
function threeWayQuicksort(a, lo = 0, hi = a.length - 1) {
  if (lo >= hi) return;

  const pivot = a[lo];
  let lt = lo, i = lo + 1, gt = hi;

  while (i <= gt) {
    if (a[i] < pivot) swap(a, lt++, i++);
    else if (a[i] > pivot) swap(a, i, gt--);
    else i++;
  }

  // Tail recurse on smaller subarray for O(log n) space
  if (gt - lo < hi - lt) {
    threeWayQuicksort(a, lo, lt - 1);
    lo = gt + 1;
  } else {
    threeWayQuicksort(a, gt + 1, hi);
    hi = lt - 1;
  }

  if (lo < hi) threeWayQuicksort(a, lo, hi);
}
```

## Test Plan
- **All equal**: Verify no swaps and linear time
- **Already sorted**: Confirm correct partitioning and maintain sorted order
- **No duplicates**: Validate against standard quicksort behavior
- **Random with duplicates**: Compare against built-in sort for correctness
- **Large duplicate ratio**: Measure performance improvement vs standard quicksort

## Complexity Comparison
- **Three-way quicksort**: O(n log m) average, O(n²) worst, O(log n) space
- **Standard mergesort**: O(n log n) always, O(n) extra space

Optimal when m ≪ n (many duplicate keys).

## Why This Is Asked
This question assesses dynamic programming fundamentals through practical string segmentation, testing understanding of both top-down memoization and bottom-up tabulation approaches.

## Key Concepts
- Dynamic Programming: memoization vs. tabulation
- String matching optimization (startsWith, trie)
- Time and space trade-offs between DP approaches
- State definition and transition logic

## Code Example
```javascript
// Top-down memoized solution
function minWordSegmentsTopDown(s, dict) {
  const n = s.length;
  const memo = Array(n + 1).fill(-1);
  memo[n] = 0;

  function dfs(i) {
    if (memo[i] !== -1) return memo[i];
    let minSegs = Infinity;
    for (const word of dict) {
      if (s.startsWith(word, i)) {
        const result = dfs(i + word.length);
        if (result !== -1) {
          minSegs = Math.min(minSegs, 1 + result);
        }
      }
    }
    memo[i] = minSegs === Infinity ? -1 : minSegs;
    return memo[i];
  }
  return dfs(0);
}

// Bottom-up tabulated solution
function minWordSegmentsBottomUp(s, dict) {
  const n = s.length;
  const dp = Array(n + 1).fill(Infinity);
  dp[n] = 0;

  for (let i = n - 1; i >= 0; i--) {
    for (const word of dict) {
      if (s.startsWith(word, i)) {
        if (dp[i + word.length] !== Infinity) {
          dp[i] = Math.min(dp[i], 1 + dp[i + word.length]);
        }
      }
    }
  }
  return dp[0] === Infinity ? -1 : dp[0];
}
```

## Complexity Analysis
- **Time:** O(n × m × L) where n = |s|, m = dict size, L = avg word length. Using a Trie reduces this to O(n × L).
- **Space:** O(n) for the memo/DP array.

## Why This Is Asked
Tests DP with dual objectives: minimize cost and count optimal deletion sets, plus implement in two styles. It also covers edge cases like empty substrings and ties.

## Key Concepts
- DP on substrings; store (cost, ways).
- Memoization and bottom-up parallels; careful counting on ties.
- Modulo arithmetic for counts.

## Code Example
```javascript
// Memoized DFS
function solveMemo(s, delCost){
  const n = s.length;
  const memoCost = Array.from({length:n},()=>Array(n).fill(-1));
  const memoWays = Array.from({length:n},()=>Array(n).fill(0));
  const MOD = 1_000_000_007;
  function dfs(l,r){
    if (l>=r) return {cost:0, ways:1};
    if (memoCost[l][r]!==-1) return {cost:memoCost[l][r], ways:memoWays[l][r]};
    if (s[l]===s[r]){
      const res = dfs(l+1,r-1);
      memoCost[l][r]=res.cost;
      memoWays[l][r]=res.ways;
      return res;
    } else {
      const A = dfs(l+1,r);
      const B = dfs(l,r-1);
      let cost;
      let ways = 0;
      if (A.cost + delCost[l] < B.cost + delCost[r]){
        cost = A.cost + delCost[l];
        ways = A.ways;
      } else if (B.cost + delCost[r] < A.cost + delCost[l]){
        cost = B.cost + delCost[r];
        ways = B.ways;
      } else {
        cost = A.cost + Math.min(delCost[l], delCost[r]);
        ways = (A.ways + B.ways) % MOD;
      }
      memoCost[l][r]=cost; memoWays[l][r]=ways;
      return {cost, ways};
    }
  }
  return dfs(0,n-1);
}
```

